-- ═══════════════════════════════════════════════════════════════
-- NINA-AES — Référentiel géographique Mali (seed SQL)
-- ═══════════════════════════════════════════════════════════════
--
-- ⚠️  FICHIER GÉNÉRÉ — Ne pas éditer à la main.
--    Source de vérité : data/mali/regions.json + cercles.json
--    Régénération : node scripts/generate-seed-sql.mjs
--                 (ou : make seed-locations-generate)
--
-- Contenu :
--   - 20 régions (niveau 1)
--   - 142 cercles (niveau 2 ; total officiel attendu : 159)
--   - 10 communes (échantillon Bamako + chefs-lieux principaux)
--   - 0 arrondissements (niveau 3) — à ingérer ultérieurement via INSTAT
--   - 0 villages (niveau 6) — hors scope V1 (volume 12 712, source INSTAT requise)
--
-- Idempotent : INSERT ... ON CONFLICT (code) DO UPDATE.
-- Schéma isolé : `geo_ref` — n'interfère pas avec public.locations (Prisma).
-- ═══════════════════════════════════════════════════════════════

SET client_encoding = 'UTF8';
SET search_path = public;

-- ───────────────────────────────────────────────────────────────
-- Schema dédié au référentiel géographique statique
-- ───────────────────────────────────────────────────────────────
CREATE SCHEMA IF NOT EXISTS geo_ref;
COMMENT ON SCHEMA geo_ref IS 'Référentiel géographique Mali (régions, cercles, communes, arrondissements). Source de vérité : data/mali/*.json. Régénéré par scripts/generate-seed-sql.mjs.';

-- Table régions (niveau 1) — 19 régions + District de Bamako
CREATE TABLE IF NOT EXISTS geo_ref.regions (
  code            TEXT PRIMARY KEY,
  name_official   TEXT NOT NULL,
  name_short      TEXT NOT NULL,
  chef_lieu       TEXT NOT NULL,
  lat             NUMERIC(10, 7) NOT NULL,
  lng             NUMERIC(10, 7) NOT NULL,
  is_district     BOOLEAN NOT NULL DEFAULT FALSE,
  langues         TEXT[] NOT NULL DEFAULT '{}',
  statut_2023     TEXT,
  centroide_estime BOOLEAN NOT NULL DEFAULT FALSE
);
COMMENT ON TABLE geo_ref.regions IS '20 entités niveau 1 (19 régions + 1 District autonome de Bamako).';

-- Table cercles (niveau 2) — 159 attendus, 142 confirmés
CREATE TABLE IF NOT EXISTS geo_ref.cercles (
  code        TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  region_code TEXT NOT NULL REFERENCES geo_ref.regions(code) ON UPDATE CASCADE,
  lat         NUMERIC(10, 7) NOT NULL,
  lng         NUMERIC(10, 7) NOT NULL,
  confiance   TEXT NOT NULL DEFAULT 'haute' CHECK (confiance IN ('haute', 'moyenne', 'basse')),
  centroide_estime BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE INDEX IF NOT EXISTS cercles_region_idx ON geo_ref.cercles (region_code);

-- Table communes (niveau 4) — échantillon initial
CREATE TABLE IF NOT EXISTS geo_ref.communes (
  code        TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  parent_code TEXT NOT NULL,
  lat         NUMERIC(10, 7),
  lng         NUMERIC(10, 7)
);
CREATE INDEX IF NOT EXISTS communes_parent_idx ON geo_ref.communes (parent_code);

-- Table arrondissements (niveau 3) — réservée, vide pour V1
CREATE TABLE IF NOT EXISTS geo_ref.arrondissements (
  code        TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  cercle_code TEXT NOT NULL REFERENCES geo_ref.cercles(code) ON UPDATE CASCADE
);

-- ───────────────────────────────────────────────────────────────
-- Régions (niveau 1) — 20 entités
-- ───────────────────────────────────────────────────────────────

-- ───────────────────────────────────────────────────────────────
-- Cercles (niveau 2) — 142 confirmés / 159 attendus
-- ───────────────────────────────────────────────────────────────

-- ───────────────────────────────────────────────────────────────
-- Communes (échantillon 10 entrées)
-- ───────────────────────────────────────────────────────────────

-- ───────────────────────────────────────────────────────────────
-- Message de fin
-- ───────────────────────────────────────────────────────────────
DO $$
DECLARE
  n_regions INTEGER;
  n_cercles INTEGER;
  n_communes INTEGER;
BEGIN
  SELECT COUNT(*) INTO n_regions  FROM geo_ref.regions;
  SELECT COUNT(*) INTO n_cercles  FROM geo_ref.cercles;
  SELECT COUNT(*) INTO n_communes FROM geo_ref.communes;
  RAISE NOTICE '============================================';
  RAISE NOTICE '✅ NINA-AES — Référentiel Mali seedé';
  RAISE NOTICE '   Régions   : % / 20 (19 régions + District)',  n_regions;
  RAISE NOTICE '   Cercles   : % / 159 attendus',                n_cercles;
  RAISE NOTICE '   Communes  : % (échantillon)',                 n_communes;
  RAISE NOTICE '   Arrondissements : 0 (à ingérer V2 via INSTAT)';
  RAISE NOTICE '   Villages         : 0 (hors scope V1, 12 712 attendus via INSTAT)';
  RAISE NOTICE '============================================';
END $$;
